"""Stage 4A documentation and provisional settings only. No training entry point."""
import json,math,collections,re
from pathlib import Path
from .inspect import ROOT,OUT,dump,sha

def main(folder):
 folder=Path(folder);s=json.loads((folder/'statistics.json').read_text());arch=json.loads((OUT/'runtime-architecture.json').read_text());hdr=json.loads((OUT/'architecture.json').read_text());tax=json.loads((OUT/'failure-taxonomy.json').read_text());leak=json.loads((folder/'leakage.json').read_text());env=json.loads((OUT/'environment.json').read_text())
 train=s['splits']['train'];steps=math.ceil(train/16)
 chosen=next(x for x in arch['candidates'] if x['family']=='hybrid_attention_and_mlp' and x['rank']==8)
 projection_params=sum(math.prod(x['shape']) for x in arch['modules'].values());other=arch['base_parameters']-projection_params
 seq=4608;gib=2**30;n=chosen['parameters']
 memory=dict(unit='GiB; engineering estimates, not training measurements',quantizable_projection_parameters=projection_params,other_parameters=other,nf4_double_quantized_projection_payload=projection_params*.516/gib,nonquantized_bf16=other*2/gib,nonquantized_fp32=other*4/gib,estimated_base_preserving_bf16=(projection_params*.516+other*2)/gib,estimated_base_default_peft_fp32=(projection_params*.516+other*4)/gib,rank8_fp32_adapter_weights=n*4/gib,rank8_fp32_gradients=n*4/gib,rank8_adamw32_moments=n*8/gib,rank8_adamw8_moments_lower_bound=n*2/gib,checkpoint_layer_boundary_activations=64*seq*5120*2/gib,full_bf16_logits=seq*248320*2/gib,full_fp32_logits=seq*248320*4/gib,bf16_ordinary_lora_base=arch['base_parameters']*2/gib,cuda_workspaces_fragmentation_range=[1,3],additional_attention_backward_temporaries='unknown; implementation-dependent; potentially several GiB',historical_inference_peak_torch_allocated=17.92931032180786,historical_free_after_load=6.61859130859375)
 config=dict(stage='4B PROPOSAL ONLY — NOT EXECUTABLE TRAINING',training_performed=False,model='models/Qwen3.8-27B',runtime_class=arch['class_name'],task_type='CAUSAL_LM',target_modules=chosen['target_modules'],target_scope='text hybrid attention plus MLP; exclude embeddings, lm_head, vision, convolution and normalization',r=8,r_range=[8,16],alpha=16,alpha_range=[16,32],lora_dropout=.05,dropout_range=[0,.05],bias='none',quantization=dict(load_in_4bit=True,bnb_4bit_quant_type='nf4',bnb_4bit_use_double_quant=True,bnb_4bit_compute_dtype='bfloat16',bnb_4bit_quant_storage='uint8'),gradient_checkpointing=True,gradient_checkpointing_kwargs={'use_reentrant':False},use_cache=False,optimizer='paged_adamw_8bit (provisional; validate states and paging)',learning_rate=5e-5,learning_rate_range=[5e-5,1e-4],scheduler='linear',warmup_ratio=.05,weight_decay=.01,max_grad_norm=1.0,micro_batch_size=1,gradient_accumulation_steps=16,effective_batch=16,epochs=2,max_steps_provisional=steps*2,steps_per_epoch=steps,sequence_length=seq,packing=False,padding='dynamic right; attention=0 and labels=-100 on padding',loss='assistant JSON plus one im_end only; prompt, header and empty think block -100',evaluation_steps=steps//2,checkpoint_steps=steps,save_total_limit=2,seed=410042,eval_seed=410043,model_selection='validation only; final internal test and all historical benchmarks locked',installed_versions=env,required_feasibility_checks=['PEFT preparation upcast audit; frozen embeddings/head precision must be explicit','hybrid attention checkpoint/backward implementation and finite gradients','large-vocabulary logits and loss peak memory; compatible chunked/fused loss requires independent equivalence checks','no silent truncation at 4608; length bucketing is permitted','GPU allocated/reserved/device peaks with safety margin, throughput and optimizer paging','base parameter requires_grad=False; only intended adapter parameters trainable; base hashes unchanged'],decision='Prefer QLoRA to ordinary LoRA, but one-A30 training is NOT yet demonstrated feasible.')
 dump(OUT/'proposed-stage4b-config.json',config);dump(OUT/'memory-estimate.json',memory)
 # Keep actual overlength identities visible; do not remove or truncate them.
 over=[];rows=[]
 from transformers import AutoTokenizer
 from .data import tokenized
 tok=AutoTokenizer.from_pretrained(ROOT/'models/Qwen3.8-27B',local_files_only=True)
 for split in ['train','validation','test']:
  for line in (folder/(split+'.jsonl')).read_text().splitlines():
   r=json.loads(line);rows.append(r);e=tokenized(r,tok)
   if e['total_tokens']>4096:over.append(dict(example_id=r['metadata']['example_id'],split=split,scenario_family=r['metadata']['scenario_family'],variant=r['metadata']['variant'],label=r['metadata']['expected_label'],input=e['input_tokens'],target=e['target_tokens'],total=e['total_tokens'],reason='four directly supported components, five evidence groups and exact quotation/citation overhead'))
 dump(OUT/'sequence-risk.json',dict(proposed_sequence_length=seq,over_4096=over,over_4608=[],truncated_examples=0))
 lines=[]
 def section(n,title,text):lines.extend([f'## {n}. {title}','',text,''])
 def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(x) for x in row)+' |' for row in rows])
 lines=['# Stage 4A — QLoRA dataset and objective design','', 'Status: dataset v1 frozen after all acceptance gates. No Qwen training, adapter creation, optimizer step, GPU request, weight modification, RAG change or Stage 4B execution occurred.','']
 section(1,'Frozen Stage 3J reference','`results/stage3j/frozen-rag-configuration.json`, SHA-256 `'+sha(ROOT/'results/stage3j/frozen-rag-configuration.json')+'`. Stage3A canonical evidence; Stage3B 640-character/96-overlap chunks; pinned MiniLM 384-dimensional embeddings; Stage3D vector contract; structural-extractive-v1 decomposition; focused-exact-acronym-v2 queries; internal K=20; compound shortlist=2; atomic shortlist=5; cosine floor=.20; component-round-robin-audited-v2; maximum five groups; identity-v1 reranker; unchanged trust, provenance and tenant/candidate scope. Full configuration remains external and byte-identical.')
 section(2,'Qwen failure taxonomy','`results/stage4a/failure-taxonomy.json` extracts '+str(len(tax['records']))+' historical failure records from RAG arms with no retrieval loss and matching contextual/full gold. These include repeated needs across scales/arms and are not independent population observations. Stage3J primary evidence arrived correctly: h02 under-recognized deployment; h05/h07 had wrong component judgments; h11–h14 confused related evidence with contradiction. Its report records 12 false contradictions, 52 existing non-entailing citations and two unauthorized-ID occurrences. Stage3J unjustified-partial and explicit injection-success counts were zero; those remain preventive curriculum objectives, not invented Stage3J failures. Historical row text is never copied into generation.')
 section(3,'Training objectives','\n'.join('- **'+x['id']+'** ('+x['status']+'): '+x['objective'] for x in tax['objectives']))
 section(4,'Dataset architecture','1,920 authored synthetic records: 60 substantive scenarios grouped into 12 parent template families, eight contextual variants, four target labels. Each record separates `messages` from `metadata` and a structured `oracle`. Only `messages` may enter future training. Oracle predicates carry event identity, positive/adjacent/denial relation, exact values, source lineage and authenticated verification; no model-generated labels or real profiles are used.')
 section(5,'Input format','The unmodified `rag.component.retrieve.messages` (also used by Stage3J) constructs system/user messages. User JSON retains task need ID, original requirement, authored atomic components, conservative retrieval decomposition, retrieval notice, `UNTRUSTED_RETRIEVED_EVIDENCE`, closing marker and the frozen output schema. Every evidence entry retains source type, acquisition origin, untrusted-data status, verification policy, exact-support attestations, content and version/span citation handle. Synthetic contexts obey exact-text grouping and the five-group/640-character bounds. Optional rank/score/query diagnostics are omitted: no actual vector search occurred and fabricated scores would be misleading. No scope IDs, oracle relations, expected labels, difficulty, secrets or database internals enter model input. As in historical preparation, authored judgment components coexist with conservative retrieval decomposition. Historical records about a different engagement remain active-source text; inactive records are never smuggled past the frozen lifecycle boundary.')
 section(6,'Output format','The exact frozen `rag/reasoning/schema.json` is copied as `target-schema.json`. It includes information_need_id, overall label, atomic component_id/claim/label/evidence_ids/quotes/reason, union evidence_ids, missing_evidence and concise overall reason. Quotes are verbatim, citations must entail the exact atom, and UNKNOWN uses empty citations. The inherited rule requiring missing_evidence on explicit denials remains intact; those entries request resolution of the contradictory record. Frozen aggregation: all supported → supported; any supported/partial plus incomplete → partial; otherwise any explicit contradiction → unsupported; otherwise unknown. In particular, support + contradiction remains PARTIALLY_SUPPORTED. No free-form hidden reasoning is generated.')
 section(7,'Chat template','System text is byte-identical `system_v2.txt` / stage3g-v2. The tokenizer is the existing local `models/Qwen3.8-27B`; its actual runtime is Qwen3_5ForCausalLM. No directory/model rename or substitution occurred. Tokenizer config, vocabulary, merges, tokenizer JSON and chat-template file hashes are in the release manifest. `enable_thinking=False`; inference prefix uses `add_generation_prompt=True`; full three-message training rendering uses `False`. Prefix equality is asserted at both text and token level. This tokenizer inserts an empty think block in the assistant prefix even with thinking disabled; it is preserved and masked. No additional special tokens are added.')
 section(8,'Loss masking','Causal next-token loss applies only to assistant JSON and exactly one `<|im_end|>` token. System, user/RAG text, assistant header, empty think block and right padding have labels -100. The formatting newline after im_end is excluded. Labels remain unshifted for the model loss to shift once; a boundary test verifies that the last prompt position predicts the first JSON token. Padding uses the actual tokenizer pad ID with attention_mask=0; it is never inferred from token value. `loss-mask-audit.json` records boundary token strings/labels, EOS IDs and padding tests. This stage constructs arrays only; it never computes model loss or backward gradients.')
 section(9,'Scenario/template families',table(['Parent family','Split','Examples','Scenarios'],[(k, next(r['metadata']['split'] for r in rows if r['metadata']['template_family']==k),v,5) for k,v in sorted(s['template_families'].items())])+'\n\nTraining retains all ten core technology/action/numeric/verification families. Validation holds out assertion-reporting templates; internal TEST holds out observability/automation action templates. This deliberately tests transfer and avoids certificate-name substitutions leaking across splits. All 60 scenario predicates and domain-specific compound companions are explicit in generation_config.json.')
 section(10,'Hard negatives',str(s['hard_negative']['True'])+' examples (46.875%) have nonempty insufficient/partially sufficient contexts. Contrasts include Docker/Kubernetes, AWS/Azure/GCP, Flask/FastAPI, TensorFlow/PyTorch/JAX, generic SQL/PostgreSQL, API consumption/construction, LoRA/QLoRA, four-bit inference/training, RAG/fine-tuning, study/implementation and deployment/production operation. RELATED never supplies partial credit by itself. Direct paraphrased positives constitute a balanced 25%, so the dataset does not reward universal abstention.')
 section(11,'Counterfactual and numeric pairs','480 scenario groups keep all four labeled variants together. Atomic evidence variants provide controlled support/adjacent/explicit-denial comparisons with the same requested predicate; partial variants add a genuinely supported material component. Compound variants are multi-fact exercises rather than claimed one-fact counterfactuals. Five numeric scenarios cover latency percentage, currency savings, throughput, record counts and team size. Same-event exact values support, generic improvements do not, and explicitly corrected different values contradict. Different-event direct records do not establish a current-event claim.')
 section(12,'Citation design','An independent proposition rule resolves each atom from same-event, same-predicate facts and exact verification state. Positive and contradictory atoms cite a deterministic entailing record with an exact quote; unresolved conflicts cite nothing. The standalone validator checks the frozen schema, every ID and owner, quote membership, citation union, entailment, atomic coverage and frozen aggregation. Renderer/catalog checks also reject edited technologies, actions, numeric literals, provenance and malformed evidence. Mutation tests show that existing but non-entailing IDs are rejected. This is a closed synthetic oracle, not a general natural-language entailment classifier.')
 section(13,'Trust, corroboration and security','240 records (12.5%) contain untrusted commands, including requests to output SUPPORTED or use candidate B. They remain quoted evidence data and are never cited as factual proof. No foreign evidence entry is included; ownership mutation tests reject it. Candidate assertions are not independent verification, and source type never creates an attestation. Duplicate copies preserve one lineage and do not become independent proofs. Separately observed records retain independent lineage; neither repetition nor corroboration repairs a missing predicate. Unresolved direct conflicts yield UNKNOWN. Authenticity is simulated by the trusted generator for synthetic examples only.')
 section(14,'Generation and revision history','Seed 410042 and explicit Python templates; no generative model is used. Candidate-01 established the initial token distribution. Candidate-02 strengthened schema validation without changing messages. Candidate-03 added domain-specific companion claims and five-group contexts. Candidate-04 grouped certificate/tool substitutions at the parent-template boundary and enforced the 4,608-token limit. Candidate-05 bounded percentage reductions to physically meaningful values, added three-supported/one-missing compound patterns, and removed ambiguous negative wording from adjacent RAG evidence. Earlier candidates and diagnostic logs remain as development history, not frozen training releases. No rejected example is silently repaired; systemic changes are recorded in generation-revisions.json. Deterministic tests compare every regenerated record and stable ID.')
 section(15,'Total examples',str(s['examples'])+'. The measured coverage supports a compact first experiment; multiplying near-identical paraphrases would add volume more than independent information. This is an initial synthetic curriculum, not a claim that 1,920 examples are sufficient for deployment.')
 section(16,'TRAIN',str(s['splits']['train'])+' examples, 50 scenarios, 10 parent templates (83.333%). Only this split receives future optimizer updates.')
 section(17,'VALIDATION',str(s['splits']['validation'])+' examples, five scenarios, one held-out parent template (8.333%). Used for future selection/checking; never trained.')
 section(18,'TEST',str(s['splits']['test'])+' examples, five scenarios, one held-out parent template (8.333%). Locked for final Stage4D use. Ratios favor whole-family isolation over forced 80/10/10. Internal held-out splits are intentionally narrow domain-transfer probes; they cannot replace the broader historical external suite.')
 section(19,'Label distribution',table(['Label','All','Train','Validation','Test'],[(label,s['labels'][label],*[s['by_split'][k]['labels'][label] for k in ['train','validation','test']]) for label in sorted(s['labels'])])+'\n\nAtomic/compound: '+str(s['compound'])+'. All four labels are balanced within every split. Numeric cases: '+str(s['numeric'])+'. Citation atoms: '+str(s['citation_atoms'])+'. Domain/action/trust distributions are fully enumerated in statistics.json; trust tags can overlap and are not exclusive counts.')
 section(20,'Scenario distribution','60 scenario families × 32 examples; 12 parent template families × 160 examples. No parent accounts for more than 8.333% of the whole dataset (10% of TRAIN). Source shapes span zero through five evidence groups: '+str(s['evidence_groups'])+'. Exact per-scenario/domain/action distributions are in statistics.json and generation_config.json.')
 section(21,'Difficulty distribution',table(['Difficulty','Count'],sorted(s['difficulty'].items()))+'\n\nDifficulty is metadata only, assigned from evidence context and ambiguity. It is a sampling/analysis heuristic, not an empirically measured Qwen difficulty score.')
 section(22,'Measured tokenizer statistics',table(['Tokens','Mean','Median','p90','p95','Maximum','Volume'],[(k,round(v['mean'],2),v['median'],v['p90'],v['p95'],v['maximum'],v['sum']) for k,v in s['tokens'].items()])+'\n\nCounts include the real chat-template prefix and supervised assistant end token. Token analysis is CPU-only and uses the local tokenizer, not a character estimate.')
 section(23,'Sequence length recommendation','Use max_length=4608 with dynamic padding and no truncation. Maximum measured total is '+str(s['tokens']['total_tokens']['maximum'])+'. Nine examples exceed 4096; all are identified in results/stage4a/sequence-risk.json with their split, input/target counts and reason. They have four supported components, five groups and citation/quote overhead. None exceeds 4608 or the frozen 1536 assistant-output cap. Sequence length must not be reduced by silently dropping components or evidence; Stage4B must demonstrate memory feasibility for the longest examples.')
 section(24,'Leakage analysis','Known leakage: zero. Exact and normalized context duplication, scenario IDs, candidate entities and parent-template IDs are split-isolated. Technology-substitution siblings share a parent group. Cross-split substantive-predicate token Jaccard maximum: '+str(leak['max_cross_split_family_token_jaccard'])+'; review threshold .85. Common JSON/schema text, IDs and entities are excluded from that template comparison. Historical five-gram overlap maximum: '+str(leak['max_historical_fivegram_jaccard'])+'. Lexical thresholds are practical audits, not proofs of semantic independence; generic reasoning operators and some companion predicates intentionally recur.')
 section(25,'Historical benchmark exclusion','The release contains '+str(leak['historical_fingerprint_count'])+' normalized historical fingerprints with original file SHA-256 hashes in historical-exclusion.json. Requirements, atomic claims and evidence from Stage3G–3J datasets and prepared fixtures are checked. There are zero exact/normalized benchmark collisions and zero high-overlap historical matches. No external benchmark is present in TRAIN, VALIDATION or internal TEST. Historical taxonomy records live only in results/stage4a, never in model messages.')
 section(26,'Standalone validation','`PYTHONDONTWRITEBYTECODE=1 .venv/bin/python -B -m stage4a.validate datasets/stage4a/v1` parses the existing release without regenerating it; it exits nonzero on any failure. It validates all 1,920 records, frozen message/schema compatibility, domain/action/numeric/trust logic, ownership, citations, grouping, historical fingerprints, token lengths and file/source checksums. Both candidate and final frozen-release validations are retained as JSON. The validator accepts only the explicit authored synthetic grammar; it is intentionally fail-closed.')
 section(27,'Representative inspection','`datasets/stage4a/v1/inspection.md` and inspection-samples.json contain 35 authored samples with exact evidence and full structured targets: all labels; Kubernetes/Docker; AWS/Azure; API construction/consumption; LoRA/QLoRA and four-bit inference; RAG/fine-tuning; numbers; independently verified versus asserted credentials; deployment positives; four-component partial support; mixed support/denial; unresolved conflict; duplicate lineage; and malicious evidence. Manual inspection found the need for parent-family split strengthening and realistic compound/five-group contexts before the final freeze. Optional new base-Qwen replay was deliberately deferred: no GPU was allocated and no new model accuracy is claimed.')
 section(28,'Synthetic limitations and curriculum','Language and denial phrasing remain repetitive; formal predicate rules simplify natural ambiguity; source authentication is synthetic; only eight context patterns and three companion-claim slots per domain are modeled. Shuffled order, paraphrased positives, varied ordering/source origin, distractors, conflicting and historical-event records, injection and exact duplicates reduce but do not eliminate shortcuts. Parent-group isolation prevents trivial substitution leakage. Start with shuffled mixed training and natural balanced sampling; no label weights or phased curriculum are justified by these counts. Track later results by label, scenario, difficulty, source/trust and length; add genuinely new authored templates only as a new version, never tune individual final-test examples.')
 section(29,'QLoRA versus ordinary LoRA','Ordinary BF16 LoRA would require approximately '+str(round(memory['bf16_ordinary_lora_base'],2))+' GiB for the frozen text weights alone, exceeding an A30’s 24 GiB before activations or adapters. Existing NF4 inference works, so QLoRA is the practical direction. NF4 and double quantization compress the frozen base; paging can moderate optimizer spikes but cannot remove activation cost. See [QLoRA paper](https://arxiv.org/abs/2305.14314) and [PEFT quantization guidance](https://huggingface.co/docs/peft/developer_guides/quantization). QLoRA adds quantization/backward complexity and can be slower than BF16 LoRA; neither stability nor training fit has been measured here.')
 section(30,'Actual target modules and parameter counts','Safetensors headers and an empty meta-device runtime independently agree on '+str(arch['base_parameters'])+' text parameters; the full checkpoint has '+str(hdr['checkpoint_parameters'])+' including vision. Runtime Qwen3_5ForCausalLM uses 48 linear-attention and 16 full-attention layers. Available projections: q_proj/k_proj/v_proj/o_proj; in_proj_qkv/in_proj_z/in_proj_a/in_proj_b/out_proj; gate_proj/up_proj/down_proj. q_proj includes a gate and is not inferred from a generic Qwen recipe.\n\n'+table(['Scope','r','Modules','Adapter parameters','% text base'],[(x['family'],x['rank'],x['module_count'],x['parameters'],round(x['percent_base'],4)) for x in arch['candidates']])+'\n\nPropose rank-8 hybrid attention + MLP (496 exact module paths recorded). Full-attention-only reaches only 16 layers. Hybrid-attention-only is a lower-memory ablation; MLP inclusion follows the broad projection coverage used in QLoRA practice. Exclude embeddings, lm_head, vision, convolution and normalization. These are arithmetic counts, not instantiated adapters.')
 section(31,'Rank, alpha, dropout','Initial r=8, alpha=16, dropout=.05, bias=none, task_type=CAUSAL_LM. Compare r=16/alpha=32 only if validation and measured headroom justify it; .00–.05 dropout is a small-data stability range. Rank8 gives '+str(n)+' prospective trainable parameters ('+str(round(chosen['percent_base'],4))+'%). No adapter parameters were allocated. All exact runtime paths are in proposed-stage4b-config.json; Stage4B must verify the trainable-name/count audit.')
 section(32,'Quantization proposal','Reuse proven bitsandbytes NF4, double quantization, uint8 storage and BF16 compute. Enable non-reentrant gradient checkpointing and disable inference KV cache during training. Installed PEFT preparation casts non-Params4bit BF16/FP16 tensors to FP32. That can upcast the large input embedding and output head and materially increase memory. Stage4B must inspect this transition, and any deliberate retention of frozen embeddings/head in BF16 requires finite-gradient and loss-equivalence checks; no precision change is made in Stage4A.')
 section(33,'Optimizer, learning rate and schedule','Provisional paged_adamw_8bit, LR 5e-5 (compare at most 1e-4 after a stable smoke run), linear decay, 5% warmup, weight decay .01 and gradient clipping 1.0. Lower initial LR limits overshooting a small, structured dataset. Validate optimizer state dtype/paging in the installed bitsandbytes build; paging does not guarantee fit. Versions: '+', '.join(k+'='+v for k,v in sorted(env.items()))+'. These are proposed starting values, not a tuned optimum.')
 section(34,'Batch, accumulation and steps','Microbatch1, accumulation16, effective batch16. TRAIN has '+str(train)+' examples, so '+str(steps)+' optimizer steps per epoch and '+str(steps*2)+' for a provisional two epochs; no steps have run. Train total token volume per epoch: '+str(s['by_split']['train']['tokens']['total_tokens']['sum'])+'; supervised target volume: '+str(s['by_split']['train']['tokens']['target_tokens']['sum'])+'. Validate every '+str(steps//2)+' steps, checkpoint each '+str(steps)+' steps, keep two checkpoints, choose only with VALIDATION. Fixed balanced sampling and seed410042 suffice. Gradient accumulation changes effective batch, not per-example activation memory.')
 section(35,'Sequence, packing and objective execution','4,608 maximum total tokens; dynamically right-pad and bucket by measured length; no packing initially. Packing unrelated candidate conversations risks cross-example attention and incorrect label boundaries and offers limited value at microbatch1. Any future packing requires separate attention and masking equivalence tests. Loss is token-normalized over unmasked assistant targets; verify accumulation normalization so variable target lengths do not accidentally change example weighting. Generation remains the frozen inference template with thinking disabled and 1536 output cap.')
 section(36,'One-A30 feasibility estimate',table(['Component','Estimated GiB'],[(k,round(v,3)) for k,v in memory.items() if isinstance(v,(float,int)) and not k.endswith('parameters')])+'\n\nThe NF4 payload estimate uses about .516 bytes per quantized projection parameter and excludes allocator/quantizer implementation details. BF16 base plus rank8 adapters/states, checkpoint boundaries, full-vocabulary logits, attention/backward temporaries and CUDA workspaces can exceed 24 GiB. Default PEFT FP32 upcasting leaves still less headroom. BF16-preserved base with compatible chunked/fused loss and measured checkpoint behavior may fit, but is unproven. Standard full-logit/default-upcast training is a high OOM risk. Stage4B must measure load → preparation → forward → backward → optimizer peaks, allocated/reserved/device memory, paging and tokens/sec on the longest records. If it cannot fit safely, report the blocker and evaluate an explicitly justified memory strategy; do not truncate data or assume successful inference proves training feasibility.')
 testlog=(OUT/'stage4a-tests.log').read_text();m=re.search(r'Ran (\d+) tests',testlog);reg=json.loads((OUT/'regression.json').read_text());pres=json.loads((OUT/'preservation.json').read_text())
 section(37,'Stage 4A tests',str(m.group(1))+' tests pass. Coverage includes deterministic generation/IDs, strict schema, all labels/balance, atomic and compound composition, every required technology/action contrast, numbers, citations/quotes, verification, injection, privacy/ownership, grouped splits/duplicates/historical exclusion, tokenizer/chat compatibility, sequence risk, causal loss/padding masks, manifest/checksums and standalone failure exits. No training test or optimizer is executed.')
 section(38,'Historical regression tests',str(reg['total_tests'])+' prior tests pass (467 Stage3, 19 Stage1/2), with unchanged frozen Stage2 replay, Stage3A/B demos, Stage3E 112-case replay and Stage3F 297 learned/identity replay configurations. The first Stage3F exact-score replay failed on compute-3-04; differences were recorded rather than weakening equality. The complete original replay then ran CPU-only on gpu-4-23, the historical Stage3J verification node, without a GPU allocation. This is a hardware-sensitive bitwise reproducibility limit, not evidence that the frozen identity RAG was changed. Previous failed-attempt logs remain preserved.')
 section(39,'Protected artifacts',str(pres['files'])+' Stage1–3J files, including weights, embedding assets and historical caches, remain byte-identical: zero changed/missing. The inherited Stage3J protected and final manifests were verified before work; Stage4A’s superset protection manifest was verified again after regressions. All new data, tests, source, logs and reports use Stage4A paths. Python bytecode writes were disabled; the existing environment was not replaced.')
 section(40,'Manifest and checksums','`datasets/stage4a/v1/manifest.json` records version, UTC generation/freeze timestamps, seed, generator/schema/frozen-contract identities, tokenizer/template hashes, split/label/scenario/difficulty counts, token statistics, historical exclusion fingerprints, generator/source hashes and SHA-256 for every release payload. `checksums.sha256` anchors manifest and payloads; `results/stage4a/final-manifest.json` covers Stage4A source, tests, documentation and acceptance artifacts. Reproduction creates a new destination; existing v1 is never overwritten. Reproduced JSONL bytes must match; timestamps naturally differ.')
 section(41,'Exact next-stage boundary','Stage4A ends here. Stage4B is limited to a separately authorized configuration/compatibility/memory smoke experiment using TRAIN and VALIDATION; it must validate module selection, masks, precision, finite gradients and one-A30 headroom before full training. Stage4C would train on TRAIN and select with VALIDATION. Stage4D alone opens internal TEST and frozen historical Stage3G–3J external benchmarks, ideally supplemented with separately authored unseen challenges frozen before training decisions. Do not tune Stage4C repeatedly against those final sets. This report and JSON configuration are proposals only: no Stage4B job, SFT, LoRA/QLoRA training, adapters, weight changes or downstream application workflows were started.')
 path=ROOT/'docs/stage4a_report.md';path.write_text('\n'.join(lines)+'\n');(OUT/'final-report.md').write_bytes(path.read_bytes())
 print('REPORT WRITTEN',path,flush=True)
if __name__=='__main__':
 import sys
 main(sys.argv[1])
